const raw = $input.first().json;
const body = raw.body || raw;
const payload = body.payload || {};

const name = payload.name || [payload.first_name, payload.last_name].filter(Boolean).join(' ') || 'there';
const firstName = payload.first_name || name.split(' ')[0] || 'there';
const email = (payload.email || '').trim();

// Calendly's v2 webhook payload nests the booked event under
// payload.scheduled_event. Fall back gracefully if that shape ever changes
// (verify against a real test booking's execution log before trusting this).
const se = payload.scheduled_event || {};
const eventName = se.name || 'Private Lesson';
const startTimeRaw = se.start_time || '';
const locationInfo = se.location || {};
const location = locationInfo.location || locationInfo.type || 'Location to be confirmed, check with Kareesa';

let startTimeCentral = '';
if (startTimeRaw) {
  try {
    startTimeCentral = new Date(startTimeRaw).toLocaleString('en-US', {
      timeZone: 'America/Chicago',
      weekday: 'long', month: 'long', day: 'numeric',
      hour: 'numeric', minute: '2-digit', timeZoneName: 'short',
    });
  } catch (e) {
    startTimeCentral = '';
  }
}

// Phone: text_reminder_number if the invitee opted into SMS reminders,
// otherwise scan custom questions for anything phone shaped.
let phone = payload.text_reminder_number || '';
const qa = Array.isArray(payload.questions_and_answers) ? payload.questions_and_answers : [];
if (!phone) {
  const phoneQA = qa.find(q => /phone|cell|mobile/i.test(q.question || ''));
  if (phoneQA) phone = (phoneQA.answer || '').replace(/[^\d+]/g, '');
}

const notes = qa.map(q => `${q.question}: ${q.answer}`).join('\n');

return {
  json: {
    eventType: body.event || '',
    status: payload.status || '',
    firstName, name, email, phone,
    eventName, startTimeRaw, startTimeCentral, location, notes,
  }
};
